import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    found = False
    for proc in psutil.process_iter(['name']):
        if proc.info['name'] == process_name:
            found = True
            break
    if not found:
        subprocess.Popen([process_name])
        return f"Process not found. Starting {process_name}."
    else:
        for proc in psutil.process_iter(['name']):
            if proc.info['name'] == process_name:
                proc.terminate()
                time.sleep(0.5)
                break
        subprocess.Popen([process_name])
        return f"Process found. Restarting {process_name}."

import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == 'Windows':
        cmd = ['start', url]
    elif system == 'Darwin':
        cmd = ['open', url]
    else:
        cmd = ['xdg-open', url]
    process = subprocess.Popen(cmd, shell=True)
    time.sleep(0.5)
    return process.poll()

