import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder):
        return {'success': False, 'message': 'Source folder does not exist.', 'failed_files': []}
    os.makedirs(dst_folder, exist_ok=True)
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file_path in files:
        if os.path.isfile(file_path):
            filename = os.path.basename(file_path)
            try:
                process = subprocess.Popen(['gzip', file_path])
                process.wait()
                if process.returncode != 0:
                    failed_files.append(filename)
                    continue
                gz_file = file_path + '.gz'
                shutil.move(gz_file, os.path.join(dst_folder, filename + '.gz'))
            except Exception:
                failed_files.append(filename)
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully.' if success else f'{len(failed_files)} file(s) failed.'
    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    proc = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    pid = proc.pid
    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()
    while proc.poll() is None and time.time() - start_time < timeout:
        try:
            p = psutil.Process(pid)
            if p.status() == psutil.STATUS_ZOMBIE:
                break
            cpu_usage += p.cpu_percent(interval=0.1)
            memory_usage += p.memory_info().rss
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break
    if proc.poll() is None:
        proc.terminate()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}
